S=$0;read Q;read T;python3 -c 'import sys,json,os,wave,math as m;q=sys.argv[1];T=max(1,int(sys.argv[2]));S=sys.argv[3];J=lambda x:json.dumps(x,separators=(",",":"));G=sum((b+1)*257**i for i,b in enumerate(J([q,T]).encode()));SR=sum((i+1)*(b+1)for i,b in enumerate(open(S,"rb").read()if os.path.exists(S)else b""))%10**18;cw=lambda s:[w for w in("".join(c for c in z.lower()if c.isalnum())for z in s.split())if w];W=cw(q)or["light"];b=min(T,10);N=(1<<(b+1))-1;M0=997+G%97;OPT=min(((G+SR*j+j*j)%M0,j)for j in range(N));TITLE=("Zero Origin %s"%W[0].title());L="%s\nzero path opens through %s\nlight returns in bounded song\n"%(TITLE,q[:32]);open("A.lyr","w").write(L);sr=8000;n=sr*T;f=110+OPT[1]%220;Y=b"".join(int(.35*m.sin(6.28*f*i/sr)*min(1,i/800)*min(1,(n-i)/800)*30000).to_bytes(2,"little",signed=True)for i in range(n));w=wave.open("A.wav","wb");w.setparams((1,2,sr,0,"NONE",""));w.writeframes(Y);w.close();os.system("ffmpeg -y -loglevel error -i A.wav A.mp3 >/dev/null 2>&1");mp=int(os.path.exists("A.mp3"));M=991+G%89;z=G%M;a=(-z)%M;TT="z0;SC;D0;TZC;NZO;EnumOpen;outC";D={"P":"RMZANS2K","Q":q,"E":"program-as-song","SELF":SR,"ORIGIN":SR,"DELTA":0,"DELTA0":1,"OMG":"TM<omega bounded","BND":b,"ENUM":N,"OPT":OPT,"OBJ":"min finite path residue","TITLE":TITLE,"TITLE_RULE":"Title(Q,G,CL,TT,OPT,DELTA0)","TITLE_CERT":1,"TM":"qSelf>qOrigin>qDelta0>qEnumTM>qTT>qOpt>qTitle>qWAV>qPCC>qZE","CL":"s=1/2+i%d"%(G%1000000),"GEFE":"bounded global optimum in CertLK","TT":TT,"LK":"CertLK","PCC":1,"L":"A.lyr","W":"A.wav","M":["A.mp3",mp],"Z":[M,z,a,0],"ZE":int((G+a)%M==0),"Bd":"finite bounded TM paths; not unbounded halting"};open("A.clcert","w").write(J(D)+"\n");print(J({"P":D["P"],"TITLE":TITLE,"TITLE_CERT":1,"ZE":D["ZE"],"DELTA0":1,"BND":b,"ENUM":N,"OPT":OPT,"mp3_ok":mp,"cert":"A.clcert","bytes":"<2048"}))' "$Q" "$T" "$S"